<?php
namespace App\Http\Controllers;
use App\Domain\Authorization\Services\PermissionResolver;use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Domain\Documents\Services\DocumentAccessRecorder;use App\Models\Document;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Symfony\Component\HttpFoundation\StreamedResponse;
class DocumentFileController extends Controller{public function preview(Request $request,Document $document,AuthorizedDocumentQuery $authorized,PermissionResolver $permissions,DocumentAccessRecorder $access):StreamedResponse{abort_unless($permissions->allows($request->user(),'documents.preview'),403);abort_unless($authorized->for($request->user())->whereKey($document->id)->exists(),403);$document->load('currentVersion.files');$file=$document->currentVersion?->files->firstWhere('file_role','PREVIEW')??$document->currentVersion?->files->firstWhere('file_role','OPTIMIZED')??$document->currentVersion?->files->firstWhere('file_role','MASTER');abort_unless($file,404);$access->record($document,'PREVIEW_STREAM','SUCCESS',$file);return $this->stream($request,$file,false);}public function download(Request $request,Document $document,AuthorizedDocumentQuery $authorized,PermissionResolver $permissions,DocumentAccessRecorder $access):StreamedResponse{abort_unless($permissions->allows($request->user(),'documents.download'),403);abort_unless($authorized->for($request->user())->whereKey($document->id)->exists(),403);$document->load('currentVersion.files');$file=$document->currentVersion?->files->firstWhere('file_role','OPTIMIZED')??$document->currentVersion?->files->firstWhere('file_role','MASTER');abort_unless($file,404);$access->record($document,'DOWNLOAD','SUCCESS',$file);return $this->stream($request,$file,true);}private function stream(Request $request,$file,bool $attachment):StreamedResponse{$disk=Storage::disk($file->storage_disk);abort_unless($disk->exists($file->storage_key),404);$size=$file->size_bytes;$start=0;$end=$size-1;$status=200;$range=$request->header('Range');if($range&&preg_match('/bytes=(\d*)-(\d*)/',$range,$m)){if($m[1]!=='')$start=(int)$m[1];if($m[2]!=='')$end=min((int)$m[2],$size-1);if($start>$end||$start>=$size)abort(416);$status=206;}$length=$end-$start+1;$headers=['Content-Type'=>'application/pdf','Content-Length'=>(string)$length,'Accept-Ranges'=>'bytes','Cache-Control'=>'private, no-store, max-age=0','X-Content-Type-Options'=>'nosniff','Content-Disposition'=>($attachment?'attachment':'inline').'; filename="document.pdf"'];if($status===206)$headers['Content-Range']="bytes $start-$end/$size";return response()->stream(function()use($disk,$file,$start,$length){$stream=$disk->readStream($file->storage_key);fseek($stream,$start);$remaining=$length;while($remaining>0&&!feof($stream)){$chunk=fread($stream,min(8192,$remaining));if($chunk===false)break;echo $chunk;$remaining-=strlen($chunk);}fclose($stream);},$status,$headers);}}
